package dev.pocketengine.features.automation;
import org.json.JSONObject;
import org.junit.Test;
import static org.junit.Assert.*;
public final class PlanBusinessWaitTest {
    private JSONObject metadata()throws Exception{return new JSONObject().put("eventId","event-1").put("fingerprint","a".repeat(64)).put("payloadVersion","original_channel_inbound_v1").put("payloadSha256","b".repeat(64)).put("provider","webhook").put("profileId","profile-1").put("appId","").put("transportEpoch","transport-1").put("conversationKind","dm").put("conversationId","actor-1").put("conversationParentId","").put("providerActorId","actor-1").put("ownerId","original-source-owner").put("principalId","principal-1").put("spaceId","original-source-space").put("bindingEpoch","").put("privateOwner",false);}
    @Test public void referenceIsBodyFreeExactAndScopeIsNotInferredFromSourceText()throws Exception{JSONObject metadata=metadata().put("text","not part of reference").put("sourceTaskId","not an authority");JSONObject ref=PlanBusinessWait.reference(metadata);assertFalse(ref.toString().contains("not part"));assertFalse(ref.toString().contains("sourceTaskId"));assertTrue(PlanBusinessWait.same(ref,PlanBusinessWait.standard(ref)));JSONObject changed=metadata();changed.put("eventId","event-2").put("fingerprint","c".repeat(64)).put("payloadSha256","d".repeat(64));assertTrue(PlanBusinessWait.sameAudience(ref,changed));changed.put("principalId","other");assertFalse(PlanBusinessWait.sameAudience(ref,changed));}
    @Test public void arbitraryPayloadProviderRevisionAndExtraGrantAreRejected()throws Exception{JSONObject ref=PlanBusinessWait.reference(metadata());ref.put("executionAuthorized",true);assertThrows(IllegalArgumentException.class,()->PlanBusinessWait.standard(ref));JSONObject version=PlanBusinessWait.reference(metadata());version.getJSONObject("anchor").put("payloadVersion","provider-sequence-5");assertThrows(IllegalArgumentException.class,()->PlanBusinessWait.standard(version));JSONObject hash=PlanBusinessWait.reference(metadata());hash.getJSONObject("anchor").put("payloadSha256","unknown");assertThrows(IllegalArgumentException.class,()->PlanBusinessWait.standard(hash));}
}
